	private void repositionParts() {
		if (this.partArray == null) return;

		for (HydraHeadContainer container : this.hc) {
			container.setHeadPosition();
			container.setNeckPosition();
		}
		TFPart.forEachPart(this, (part, _) -> part.setOldPosAndRot());
	}

