		this.respawnCounter = -1;

		this.headEntity = new HydraHead(hydra);
		this.headEntity.setPos(hydra.getX(), hydra.getY(), hydra.getZ());

		this.necka = new HydraNeck(this.headEntity);
		this.neckb = new HydraNeck(this.headEntity);
